#!/bin/sh
# Builds static/vendor/codemirror.js from entry.js with Bun, then prepends
# the license notices of every package that ended up in the bundle: each
# package's copyright line and one copy of each distinct license text.
set -eu
cd "$(dirname "$0")"

out=../../static/vendor/codemirror.js
tmp=$(mktemp)
trap 'rm -f "$tmp" "$tmp".*' EXIT

bun install --frozen-lockfile
bun build entry.js --minify --format=esm --target=browser --outfile "$tmp" --metafile="$tmp.meta.json"

# Package directories that contributed at least one input file to the bundle.
packages=$(grep -o '"node_modules/[^"]*"' "$tmp.meta.json" \
  | sed -e 's/^"node_modules\///' -e 's/"$//' \
  | awk -F/ '{ if ($1 ~ /^@/) print $1 "/" $2; else print $1 }' \
  | sort -u)

{
  echo "/*!"
  echo " * Markspace vendored CodeMirror bundle, generated by internal/web/vendor/codemirror/build.sh."
  echo " * Do not edit by hand. Bundled packages and their copyright notices:"
  echo " *"
  for pkg in $packages; do
    dir=node_modules/$pkg
    [ -f "$dir/package.json" ] || continue
    version=$(sed -n 's/^ *"version": *"\([^"]*\)".*/\1/p' "$dir/package.json" | head -n 1)
    license=$(sed -n 's/^ *"license": *"\([^"]*\)".*/\1/p' "$dir/package.json" | head -n 1)
    lic=$(ls "$dir"/LICENSE* 2>/dev/null | head -n 1 || true)
    copyright=""
    if [ -n "$lic" ]; then
      copyright=$(grep -m 1 '^ *Copyright' "$lic" | sed 's/^ *//' || true)
      # Keep one copy of each distinct license body, minus its leading copyright line.
      grep -v '^ *Copyright' "$lic" | sed 's/\*\//* \//g' > "$tmp.body"
      sum=$(cksum < "$tmp.body" | cut -d " " -f 1)
      [ -f "$tmp.lic.$sum" ] || cp "$tmp.body" "$tmp.lic.$sum"
    fi
    echo " * $pkg $version ($license) $copyright"
  done
  for body in "$tmp".lic.*; do
    [ -f "$body" ] || continue
    echo " *"
    sed -e '/./,$!d' -e 's/^/ * /' -e 's/ *$//' "$body"
  done
  echo " */"
} > "$tmp.banner"

cat "$tmp.banner" "$tmp" > "$out"
size=$(wc -c < "$out")
echo "wrote $out ($size bytes)"
if [ "$size" -gt 600000 ]; then
  echo "bundle exceeds the 600 KB budget" >&2
  exit 1
fi
